package com.termux.app.workspace;
import android.app.Application;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiToolsTest {
 private JSONObject tool(String t)throws Exception{return new JSONObject().put("tool",t).put("path","note.txt");}
 @Test public void chatModeDeniesEveryTool()throws Exception{for(String t:new String[]{"read","list","search","write","command"})try{LocalAiTools.authorize("chat",tool(t));fail(t);}catch(SecurityException expected){}}
 @Test public void readModeAllowsOnlyReading()throws Exception{for(String t:new String[]{"read","list","search"})LocalAiTools.authorize("read",tool(t));for(String t:new String[]{"write","command","bogus"})try{LocalAiTools.authorize("read",tool(t));fail(t);}catch(SecurityException expected){}}
 @Test public void proseAndCodeAreNeverExecuted()throws Exception{assertNull(LocalAiTools.request("Run rm -rf foo"));assertNull(LocalAiTools.request("```bash\necho hello\n```"));assertNull(LocalAiTools.request("<think>{\"tool\":\"command\",\"command\":\"echo no\"}</think>Done"));assertEquals("read",LocalAiTools.request("```tool\n{\"tool\":\"read\",\"path\":\"a\"}\n```").getString("tool"));}
 @Test public void rejectsTraversalAbsoluteAndControlPaths(){for(String p:new String[]{"../a","a/../../b","/etc/passwd","a\nb","a\u0000b"})try{LocalAiTools.checkedPath(p);fail(p);}catch(IllegalArgumentException|SecurityException expected){}assertEquals("a b.txt",LocalAiTools.checkedPath("a b.txt"));}
 @Test public void commandsAreExplicitAndRootIsRejected()throws Exception{WorkspaceStore.Session s=new WorkspaceStore.Session();s.localAccess="write";s.localCheckPaths=false;s.localProject="/";try{LocalAiTools.script(s,new JSONObject().put("tool","command").put("command","pwd"));fail();}catch(SecurityException expected){}s.localProject="/root/project";assertTrue(LocalAiTools.script(s,new JSONObject().put("tool","command").put("command","echo '$HOME'" )).contains("exec bash --noprofile --norc -c"));}
 @Test public void fileGuardsUseCanonicalRootAndReadDescriptor()throws Exception{WorkspaceStore.Session s=new WorkspaceStore.Session();s.localAccess="read";s.localProject="/root/project";String script=LocalAiTools.script(s,tool("read"));assertTrue(script.contains("realpath -m"));assertTrue(script.contains("/proc/$$/fd/3"));assertTrue(script.contains("OUTSIDE_PROJECT"));}
 @Test public void disablingPathChecksDoesNotChangePermissionMode()throws Exception{WorkspaceStore.Session s=new WorkspaceStore.Session();s.localCheckPaths=false;s.localAccess="read";s.localProject="/root/project";try{LocalAiTools.script(s,tool("write"));fail();}catch(SecurityException expected){}WorkspaceStore.Session c=s.copy();assertFalse(c.localCheckPaths);assertEquals("read",c.localAccess);assertEquals(s.localProject,c.localProject);}
 @Test public void shellGuardsRejectSymlinkEscapeAndDoNotModifyOutsideFile()throws Exception{
  java.nio.file.Path base=java.nio.file.Files.createTempDirectory(new java.io.File("build").toPath(),"local-tool-");
  try{java.nio.file.Path project=java.nio.file.Files.createDirectory(base.resolve("project")),outside=base.resolve("outside.txt");java.nio.file.Files.write(outside,"original".getBytes(java.nio.charset.StandardCharsets.UTF_8));java.nio.file.Files.createSymbolicLink(project.resolve("escape"),outside.toAbsolutePath());
   WorkspaceStore.Session profile=new WorkspaceStore.Session();profile.localAccess="write";profile.localProject=project.toAbsolutePath().toString();
   for(String action:new String[]{"read","write"}){JSONObject r=new JSONObject().put("tool",action).put("path","escape").put("text","changed");assertTrue(runScript(LocalAiTools.script(profile,r)).startsWith("3:"));}
   assertEquals("original",new String(java.nio.file.Files.readAllBytes(outside),java.nio.charset.StandardCharsets.UTF_8));profile.localCheckPaths=false;assertEquals("0:original",runScript(LocalAiTools.script(profile,new JSONObject().put("tool","read").put("path",outside.toAbsolutePath().toString()))));profile.localCheckPaths=true;
   assertEquals("0:SAVED",runScript(LocalAiTools.script(profile,new JSONObject().put("tool","write").put("path","note space.txt").put("text","hello '$HOME'\nПривет"))));
   String output=runScript(LocalAiTools.script(profile,new JSONObject().put("tool","read").put("path","note space.txt")));assertEquals("0:hello '$HOME'\nПривет",output);assertEquals(output,runScript(LocalAiTools.script(profile,new JSONObject().put("tool","read").put("path",project.toAbsolutePath().resolve("note space.txt").toString()))));
  }finally{try(java.util.stream.Stream<java.nio.file.Path> paths=java.nio.file.Files.walk(base)){paths.sorted(java.util.Comparator.reverseOrder()).forEach(x->{try{java.nio.file.Files.delete(x);}catch(Exception ignored){}});}}
 }
 private static String runScript(String script)throws Exception{Process p=new ProcessBuilder("/bin/bash","--noprofile","--norc","-c",script).redirectErrorStream(true).start();p.getOutputStream().close();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=p.getInputStream().read(b))!=-1)out.write(b,0,n);return p.waitFor()+":"+out.toString("UTF-8");}
 @Test public void pathChecksAndEnvironmentPersistAndDefaultToSafeMode()throws Exception{
  WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,s->{});store.sessions.clear();WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAi=true;p.environment="termux";p.localAccess="write";p.localCheckPaths=false;p.localProject="/root/example";p.localEnvironment="proot:ubuntu";store.sessions.add(p);store.decode(store.encode().toString());WorkspaceStore.Session read=store.sessions.get(0);assertFalse(read.localCheckPaths);assertEquals("write",read.localAccess);assertEquals("/root/example",read.localProject);assertEquals("proot:ubuntu",read.localEnvironment);assertTrue(new WorkspaceStore.Session().localCheckPaths);assertEquals("chat",new WorkspaceStore.Session().localAccess);store.close();
 }
 @Test public void modelJsonFencesInvokeStructuredTools()throws Exception{String json="{\"tool\":\"list\",\"path\":\"/sdcard\"}";for(String fence:new String[]{"json","JSON","tool",""})assertEquals("/sdcard",LocalAiTools.request("```"+fence+"\r\n"+json+"\r\n```").getString("path"));assertEquals("list",LocalAiTools.request("<think>inspect</think>```json\n"+json+"\n```").getString("tool"));}
 @Test public void parserRejectsMixedProseExtraObjectsAndWrongFields()throws Exception{String json="{\"tool\":\"list\",\"path\":\"/sdcard\"}";for(String answer:new String[]{json+" trailing",json+json,"Example: "+json,"```bash\n"+json+"\n```","```json\n"+json+"\n```\nExecute this"})assertNull(LocalAiTools.request(answer));for(String invalid:new String[]{"{\"tool\":\"read\",\"path\":5}","{\"tool\":\"read\",\"path\":\"x\",\"extra\":\"y\"}"})try{LocalAiTools.request(invalid);fail();}catch(IllegalArgumentException expected){}}
 @Test public void permissionAndScopeMatrixAreIndependent()throws Exception{for(String mode:new String[]{"chat","read","write"})for(boolean scoped:new boolean[]{true,false})for(String tool:new String[]{"list","read","search","write","command"}){WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess=mode;p.localCheckPaths=scoped;boolean expected=!mode.equals("chat")&&(!tool.matches("write|command")||mode.equals("write"))&&(!tool.equals("command")||!scoped);try{LocalAiTools.authorize(p,tool(tool));assertTrue(mode+" "+scoped+" "+tool,expected);}catch(SecurityException e){assertFalse(mode+" "+scoped+" "+tool,expected);}}}
 @Test public void scopedFullAccessCannotRunEvenHarmlessShellCommands()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="write";p.localCheckPaths=true;p.localProject="/project";for(String command:new String[]{"pwd","git status","python -c 'print(1)'","bash -c 'echo test'"})try{LocalAiTools.script(p,new JSONObject().put("tool","command").put("command",command));fail();}catch(SecurityException expected){assertTrue(expected.getMessage().contains("Path checks"));}}
 @Test public void modelInstructionsMatchActualCommandAvailability()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="write";p.localCheckPaths=true;assertTrue(LocalAiTools.instructions(p).contains("command tool is DISABLED"));assertFalse(LocalAiTools.instructions(p).contains("You may also request"));p.localCheckPaths=false;assertTrue(LocalAiTools.instructions(p).contains("You may also request"));p.localAccess="read";assertFalse(LocalAiTools.instructions(p).contains("You may also request"));assertTrue(LocalAiTools.instructions(p).contains("Writing and shell commands are forbidden"));}
}
